from functools import lru_cache
from typing import List

class Solution:
    def catMouseGame(self, graph: List[List[int]]) -> int:
        DRAW, MOUSE_WIN, CAT_WIN = 0, 1, 2
        n = len(graph)

        @lru_cache(None)
        def dfs(turn, mouse_pos, cat_pos):
            if turn == 2 * n:
                return DRAW
            if mouse_pos == 0:
                return MOUSE_WIN
            if mouse_pos == cat_pos:
                return CAT_WIN

            current_player = mouse_pos if turn % 2 == 0 else cat_pos
            default_result = MOUSE_WIN if current_player != mouse_pos else CAT_WIN
            result = default_result

            for next_pos in graph[current_player]:
                if current_player == cat_pos and next_pos == 0:
                    continue
                next_turn_result = dfs(turn + 1, next_pos if current_player == mouse_pos else mouse_pos, next_pos if current_player == cat_pos else cat_pos)
                if next_turn_result != default_result:
                    result = next_turn_result
                    if result != DRAW:
                        break

            return result

        return dfs(0, 1, 2)

