class Solution:
    def getMaximumXor(self, nums: List[int], maximumBit: int) -> List[int]:
        max_value = (1 << maximumBit) - 1
        current_xor = 0
        result = []

        for num in nums:
            current_xor ^= num
            k = max_value ^ current_xor
            result.append(k)

        return result[::-1]

class Solution:
    def checkZeroOnes(self, s: str) -> bool:
        max_ones = 0
        max_zeros = 0

        current_ones = 0
        current_zeros = 0

        for char in s:
            if char == '1':
                current_ones += 1
                max_ones = max(max_ones, current_ones)
            else:
                current_zeros += 1
                max_zeros = max(max_zeros, current_zeros)

        return max_ones > max_zeros

class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
        # Count the frequency of each element in the array
        from collections import Counter

        # Create a counter object to count occurrences of each element
        counts = Counter(nums)

        # Initialize an empty list to store elements that appear more than n/3 times
        result = []

        # Iterate over the counts dictionary to find elements that meet the condition
        for num, count in counts.items():
            if count > len(nums) // 3:
                result.append(num)

        return result

class Solution:
    def longestLine(self, mat: List[List[int]]) -> int:
        if not mat or not mat[0]:
            return 0

        rows, cols = len(mat), len(mat[0])
        dp = [[[0, 0, 0, 0] for _ in range(cols)] for _ in range(rows)]

        max_length = 0

        for i in range(rows):
            for j in range(cols):
                if mat[i][j] == 1:
                    # Horizontal
                    dp[i][j][0] = dp[i][j-1][0] + 1 if j > 0 else 1

                    # Vertical
                    dp[i][j][1] = dp[i-1][j][1] + 1 if i > 0 else 1

                    # Diagonal (top-left to bottom-right)
                    dp[i][j][2] = dp[i-1][j-1][2] + 1 if i > 0 and j > 0 else 1

                    # Anti-diagonal (bottom-left to top-right)
                    dp[i][j][3] = dp[i+1][j-1][3] + 1 if i < rows - 1 and j > 0 else 1

                    max_length = max(max_length, dp[i][j][0], dp[i][j][1], dp[i][j][2], dp[i][j][3])

        return max_length

class Solution:
    def isSubPath(self, head: Optional[ListNode], root: Optional[TreeNode]) -> bool:
        def dfs(node, lst):
            if not lst:
                return True
            if not node:
                return False
            if node.val == lst.val:
                return dfs(node.left, lst.next) or dfs(node.right, lst.next)
            return False

        if not head:
            return True
        if not root:
            return False
        return dfs(root, head) or self.isSubPath(head, root.left) or self.isSubPath(head, root.right)

class Solution:
    def minOperations(self, logs: List[str]) -> int:
        depth = 0
        for log in logs:
            if log == "../":
                depth = max(0, depth - 1)
            elif log != "./":
                depth += 1
        return depth

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0

        # Sort the numbers to simplify the process
        nums.sort()

        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if abs(nums[i] - nums[j]) <= min(nums[i], nums[j]):
                    max_xor = max(max_xor, nums[i] ^ nums[j])

        return max_xor

from typing import List
import heapq

class Solution:
    def minimumTime(self, grid: List[List[int]]) -> int:
        if grid[0][1] > 1 and grid[1][0] > 1:
            return -1

        m, n = len(grid), len(grid[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        min_time = [[float('inf')] * n for _ in range(m)]
        min_time[0][0] = 0
        pq = [(0, 0, 0)]  # (time, row, col)

        while pq:
            time, r, c = heapq.heappop(pq)

            if r == m - 1 and c == n - 1:
                return time

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    wait_time = max(0, grid[nr][nc] - time - 1) // 2 * 2
                    next_time = time + 1 + wait_time
                    if next_time < min_time[nr][nc]:
                        min_time[nr][nc] = next_time
                        heapq.heappush(pq, (next_time, nr, nc))

        return -1

class Solution:
    def getModifiedArray(self, length: int, updates: List[List[int]]) -> List[int]:
        diff = [0] * (length + 1)
        for start, end, inc in updates:
            diff[start] += inc
            diff[end + 1] -= inc

        result = [0] * length
        result[0] = diff[0]
        for i in range(1, length):
            result[i] = result[i - 1] + diff[i]

        return result

