class Solution:
    def widestPairOfIndices(self, nums1: List[int], nums2: List[int]) -> int:
        prefix_diff = {0: -1}
        max_width = 0
        diff = 0

        for i in range(len(nums1)):
            diff += nums1[i] - nums2[i]
            if diff in prefix_diff:
                max_width = max(max_width, i - prefix_diff[diff])
            else:
                prefix_diff[diff] = i

        return max_width

class Solution:
    def maximumSafenessFactor(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if grid[0][0] == 1 or grid[n-1][n-1] == 1:
            return 0

        # Step 1: Find the shortest path to each cell containing a thief
        dist = [[float('inf')] * n for _ in range(n)]
        q = deque()
        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    q.append((i, j))
                    dist[i][j] = 0

        while q:
            r, c = q.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and dist[nr][nc] > dist[r][c] + 1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))

        # Step 2: Use binary search to find the maximum safeness factor
        left, right = 0, n
        while left < right:
            mid = (left + right + 1) // 2
            visited = set()
            stack = [(0, 0)]

            while stack:
                r, c = stack.pop()
                if (r, c) in visited or grid[r][c] == 1 or dist[r][c] < mid:
                    continue
                visited.add((r, c))

                if r == n - 1 and c == n - 1:
                    return mid

                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        stack.append((nr, nc))

            right = mid - 1

        return 0

from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        rootU = self.find(u)
        rootV = self.find(v)
        if rootU != rootV:
            self.parent[rootU] = rootV
            return True
        return False

class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        # Add index to each edge for tracking
        for i in range(len(edges)):
            edges[i].append(i)

        # Sort edges by weight
        edges.sort(key=lambda x: x[2])

        # Function to calculate MST weight
        def calculateMST(n, edges, skipEdge=None, includeEdge=None):
            uf = UnionFind(n)
            mstWeight = 0
            count = 0

            if includeEdge is not None:
                u, v, w, _ = edges[includeEdge]
                uf.union(u, v)
                mstWeight += w
                count += 1

            for i in range(len(edges)):
                if i == skipEdge:
                    continue
                u, v, w, _ = edges[i]
                if uf.union(u, v):
                    mstWeight += w
                    count += 1
                    if count == n - 1:
                        break

            return mstWeight if count == n - 1 else float('inf')

        # Calculate the weight of the MST without any restrictions
        originalMSTWeight = calculateMST(n, edges)

        critical = []
        pseudoCritical = []

        for i in range(len(edges)):
            # Skip the current edge and check if the MST weight increases
            if calculateMST(n, edges, skipEdge=i) > originalMSTWeight:
                critical.append(edges[i][3])
            elif calculateMST(n, edges, includeEdge=i) == originalMSTWeight:
                pseudoCritical.append(edges[i][3])

        return [critical, pseudoCritical]

