class Solution:
    def minMovesToCaptureTheQueen(self, a: int, b: int, c: int, d: int, e: int, f: int) -> int:
        # Check if the rook can capture the queen directly
        if a == e or b == f:
            # Check if the bishop is blocking the rook's path
            if (a == c and b == d) or (c - a) * (d - b) == (e - a) * (f - b):
                return 2
            else:
                return 1

        # Check if the bishop can capture the queen directly
        if abs(c - e) == abs(d - f):
            # Check if the rook is blocking the bishop's path
            if (a == c and b == d) or (c - a) * (d - b) == (e - a) * (f - b):
                return 2
            else:
                return 1

        # If neither piece can capture the queen directly, it takes at least 2 moves
        return 2

