import math

class Solution:
    def smallestDivisor(self, nums: List[int], threshold: int) -> int:
        left, right = 1, max(nums)

        while left < right:
            mid = (left + right) // 2
            total = sum(math.ceil(num / mid) for num in nums)

            if total > threshold:
                left = mid + 1
            else:
                right = mid

        return left

class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        sorted_scores = sorted(score, reverse=True)
        ranks = {}
        medals = ["Gold Medal", "Silver Medal", "Bronze Medal"]

        for i, s in enumerate(sorted_scores):
            if i < len(medals):
                ranks[s] = medals[i]
            else:
                ranks[s] = str(i + 1)

        return [ranks[s] for s in score]

class Solution:
    def maxPalindromes(self, s: str, k: int) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                if s[i] == s[j]:
                    if j - i + 1 >= k:
                        dp[i] = max(dp[i], dp[j + 1] + 1)
                    else:
                        dp[i] = max(dp[i], dp[j + 1])

        return dp[0]

class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        i, j = 0, len(numbers) - 1
        while i < j:
            if numbers[i] + numbers[j] == target:
                return [i + 1, j + 1]
            elif numbers[i] + numbers[j] < target:
                i += 1
            else:
                j -= 1

from typing import List

class Solution:
    def loudAndRich(self, richer: List[List[int]], quiet: List[int]) -> List[int]:
        n = len(quiet)
        graph = [[] for _ in range(n)]
        answer = list(range(n))

        # Build the graph
        for a, b in richer:
            graph[b].append(a)

        # Depth-first search to find the quietest person with more or equal money
        def dfs(person):
            if graph[person]:
                for neighbor in graph[person]:
                    candidate = dfs(neighbor)
                    if quiet[candidate] < quiet[answer[person]]:
                        answer[person] = candidate
            return answer[person]

        # Perform DFS for each person
        for i in range(n):
            dfs(i)

        return answer

class Solution:
    def minimumBuckets(self, hamsters: str) -> int:
        n = len(hamsters)
        if n == 1:
            return 1 if hamsters == 'H' else 0

        buckets = 0
        i = 0
        while i < n:
            if hamsters[i] == 'H':
                if i + 1 < n and hamsters[i + 1] == '.':
                    buckets += 1
                    i += 3
                elif i > 0 and hamsters[i - 1] == '.':
                    buckets += 1
                    i += 2
                else:
                    return -1
            else:
                i += 1

        return buckets

class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(x, y):
            if x in y:
                return y
            for i in range(len(x), -1, -1):
                if x[:i] == y[-i:]:
                    return y + x[i:]
            return x + y

        def combine(a, b, c):
            ab = merge(a, b)
            abc = merge(ab, c)
            ac = merge(a, c)
            acb = merge(ac, b)
            ba = merge(b, a)
            bac = merge(ba, c)
            bc = merge(b, c)
            bca = merge(bc, a)
            ca = merge(c, a)
            cab = merge(ca, b)
            cb = merge(c, b)
            cba = merge(cb, a)
            return min(abc, acb, bac, bca, cab, cba, key=lambda s: (len(s), s))

        return min(combine(a, b, c), combine(a, c, b), combine(b, a, c), combine(b, c, a), combine(c, a, b), combine(c, b, a), key=lambda s: (len(s), s))

from typing import List

class Solution:
    def meetRequirement(self, n: int, lights: List[List[int]], requirement: List[int]) -> int:
        brightness = [0] * (n + 1)

        for position, rangei in lights:
            start = max(0, position - rangei)
            end = min(n - 1, position + rangei) + 1
            brightness[start] += 1
            brightness[end] -= 1

        current_brightness = 0
        count = 0

        for i in range(n):
            current_brightness += brightness[i]
            if current_brightness >= requirement[i]:
                count += 1

        return count

from typing import List

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        def atMostK(nums, k):
            count = 0
            left = 0
            for right in range(len(nums)):
                if nums[right] % 2 == 1:
                    k -= 1
                while k < 0:
                    if nums[left] % 2 == 1:
                        k += 1
                    left += 1
                count += right - left + 1
            return count

        return atMostK(nums, k) - atMostK(nums, k - 1)

from typing import List

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        def atMostK(nums, k):
            count = 0
            i = 0
            for j in range(len(nums)):
                if nums[j] % 2 == 1:
                    k -= 1
                while k < 0:
                    if nums[i] % 2 == 1:
                        k += 1
                    i += 1
                count += j - i + 1
            return count

        return atMostK(nums, k) - atMostK(nums, k - 1)

from typing import List

class Solution:
    def simulationResult(self, windows: List[int], queries: List[int]) -> List[int]:
        window_dict = {window: index for index, window in enumerate(windows)}

        for query in queries:
            current_index = window_dict[query]
            # Move the queried window to the front
            windows.insert(0, windows.pop(current_index))
            # Update the dictionary indices
            for window in window_dict:
                if window_dict[window] < current_index:
                    window_dict[window] += 1
            window_dict[query] = 0

        return windows

