class Solution:
    def numWays(self, words: List[str], target: str) -> int:
        MOD = 10**9 + 7
        n, m = len(words[0]), len(target)
        count = [Counter(word[i] for word in words) for i in range(n)]

        dp = [0] * (m + 1)
        dp[0] = 1

        for i in range(n):
            for j in range(m, 0, -1):
                dp[j] = (dp[j] + dp[j-1] * count[i][target[j-1]]) % MOD

        return dp[m]

class Solution:
    def findInteger(self, k: int, digit1: int, digit2: int) -> int:
        if digit1 > digit2:
            digit1, digit2 = digit2, digit1

        queue = [digit1, digit2]
        while queue:
            num = queue.pop(0)
            if num % k == 0 and num > k:
                return num
            if num > 2**31 - 1:
                continue
            if digit1 != 0:
                queue.append(num * 10 + digit1)
            if digit2 != 0:
                queue.append(num * 10 + digit2)

        return -1

class Solution:
    def getLastMoment(self, n: int, left: List[int], right: List[int]) -> int:
        if not left and not right:
            return 0

        max_left = max(left) if left else 0
        min_right = n - min(right) if right else n

        return max(max_left, min_right)

class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        index_map_s = {char: idx for idx, char in enumerate(s)}
        index_map_t = {char: idx for idx, char in enumerate(t)}

        permutation_difference = 0
        for char in s:
            permutation_difference += abs(index_map_s[char] - index_map_t[char])

        return permutation_difference

class Solution:
    def shortestWordDistance(self, wordsDict: List[str], word1: str, word2: str) -> int:
        # Find the indices of word1 and word2 in the list
        index1 = wordsDict.index(word1)
        index2 = wordsDict.index(word2)

        # Initialize variables to store the minimum distance
        min_distance = float('inf')

        # Iterate through the list starting from both indices
        for i in range(index1 + 1, len(wordsDict)):
            if wordsDict[i] == word2:
                # Calculate the distance between word1 and word2
                distance = abs(i - index1)
                # Update the minimum distance if the current distance is smaller
                if distance < min_distance:
                    min_distance = distance

        # Iterate through the list starting from both indices
        for i in range(index2 + 1, len(wordsDict)):
            if wordsDict[i] == word1:
                # Calculate the distance between word1 and word2
                distance = abs(i - index2)
                # Update the minimum distance if the current distance is smaller
                if distance < min_distance:
                    min_distance = distance

        return min_distance

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
            elif char == '{':
                stack.append(char)
            elif char == '}':
                if not stack:
                    return False
                stack.pop()
            elif char == '[':
                stack.append(char)
            elif char == ']':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

