from collections import deque

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        # Convert deadends to set for O(1) lookup
        dead_set = set(deadends)

        # If start is already a deadend or target is also a deadend, return -1
        if target in dead_set or "0000" in dead_set:
            return -1

        # Initialize BFS queue with starting position
        queue = deque(["0000"])
        visited = {"0000"}
        steps = 0

        while queue:
            size = len(queue)

            # Process all nodes at the current level
            for _ in range(size):
                current = queue.popleft()

                # If we've reached the target, return the number of steps
                if current == target:
                    return steps

                # Generate all possible next states by rotating each wheel
                for i in range(4):
                    for d in [-1, 1]:
                        next_state = current[:i] + str((int(current[i]) + d) % 10) + current[i+1:]

                        # If the next state is not a deadend and not visited yet, add it to the queue and mark as visited
                        if next_state not in dead_set and next_state not in visited:
                            queue.append(next_state)
                            visited.add(next_state)

            # Increment the step count after processing all nodes at the current level
            steps += 1

        # If we exhaust all possibilities without finding the target, return -1
        return -1

class Solution:
    def getLastMoment(self, n: int, left: List[int], right: List[int]) -> int:
        if not left:
            return max(right)
        if not right:
            return max(left)

        return max(max(left), n - min(right))

class Solution:
    def sumDistance(self, nums: List[int], s: str, d: int) -> int:
        n = len(nums)
        for i in range(n):
            if s[i] == 'L':
                nums[i] -= d
            else:
                nums[i] += d

        nums.sort()
        MOD = 10**9 + 7
        res = 0
        for i in range(1, n):
            res = (res + nums[i] * i - nums[i-1] * (n-i)) % MOD

        return res

