class Solution:
    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:
        def justify_line(words, width):
            if len(words) == 1:
                return words[0] + ' ' * (width - len(words[0]))

            total_spaces = width - sum(len(word) for word in words)
            num_gaps = len(words) - 1
            spaces_per_gap = total_spaces // num_gaps
            extra_spaces = total_spaces % num_gaps

            line = []
            for i in range(num_gaps):
                line.append(words[i])
                line.append(' ' * (spaces_per_gap + (1 if i < extra_spaces else 0)))
            line.append(words[-1])

            return ''.join(line)

        result = []
        current_line = []
        current_width = 0

        for word in words:
            if current_width + len(word) + len(current_line) > maxWidth:
                result.append(justify_line(current_line, maxWidth))
                current_line = [word]
                current_width = len(word)
            else:
                current_line.append(word)
                current_width += len(word)

        # Handle the last line
        last_line = ' '.join(current_line)
        result.append(last_line + ' ' * (maxWidth - len(last_line)))

        return result

