class Solution:
    def shortestSuperstring(self, words: List[str]) -> str:
        n = len(words)
        # Create a graph where graph[i][j] is the length of the overlap 
        # between the suffix of words[i] and the prefix of words[j]
        graph = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    for k in range(min(len(words[i]), len(words[j])), 0, -1):
                        if words[i][-k:] == words[j][:k]:
                            graph[i][j] = k
                            break

        # Use dynamic programming to find the shortest superstring
        dp = [[0] * n for _ in range(1 << n)]
        parent = [[-1] * n for _ in range(1 << n)]

        # Initialize the dp table
        for mask in range(1 << n):
            for bit in range(n):
                if mask & (1 << bit):
                    pmask = mask ^ (1 << bit)
                    if pmask == 0:
                        continue
                    for pbit in range(n):
                        if pmask & (1 << pbit):
                            value = dp[pmask][pbit] + graph[pbit][bit]
                            if value > dp[mask][bit]:
                                dp[mask][bit] = value
                                parent[mask][bit] = pbit

        # Find the last state with the maximum overlap
        max_overlap = 0
        last = -1
        for i in range(n):
            if dp[(1 << n) - 1][i] > max_overlap:
                max_overlap = dp[(1 << n) - 1][i]
                last = i

        # Reconstruct the path
        path = []
        mask = (1 << n) - 1
        while last != -1:
            path.append(last)
            temp = last
            last = parent[mask][last]
            mask ^= (1 << temp)

        path.reverse()

        # Build the result string
        res = words[path[0]]
        for i in range(1, len(path)):
            u, v = path[i - 1], path[i]
            res += words[v][graph[u][v]:]

        return res

