class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(a, b):
            if a in b:
                return b
            for i in range(len(b)):
                if b[i:] == a[:len(b) - i]:
                    return b + a[len(b) - i:]
            return a + b

        def merge_all(a, b, c):
            return merge(merge(a, b), c)

        # Check all possible combinations of merging
        candidates = [
            merge_all(a, b, c),
            merge_all(a, c, b),
            merge_all(b, a, c),
            merge_all(b, c, a),
            merge_all(c, a, b),
            merge_all(c, b, a)
        ]

        # Filter out candidates that do not contain all three strings
        valid_candidates = [s for s in candidates if a in s and b in s and c in s]

        # Return the lexicographically smallest candidate
        return min(valid_candidates, key=lambda x: (len(x), x))

