class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        total_sum = sum(arr)
        if total_sum % 3 != 0:
            return False

        target_sum = total_sum // 3
        count = 0
        current_sum = 0

        for num in arr:
            current_sum += num
            if current_sum == target_sum:
                count += 1
                current_sum = 0

        return count == 3

class Solution:
    def minMovesToCaptureTheQueen(self, a: int, b: int, c: int, d: int, e: int, f: int) -> int:
        # Check if rook can capture the queen in one move
        if a == e or b == f:
            # Check if bishop is blocking the rook's path
            if a == e and c == e:
                if (min(b, f) < d < max(b, f)):
                    return 2
            if b == f and d == f:
                if (min(a, e) < c < max(a, e)):
                    return 2
            return 1

        # Check if bishop can capture the queen in one move
        if abs(c - d) == abs(e - f):
            # Check if rook is blocking the bishop's path
            if abs(a - b) == abs(c - d):
                if (min(c, e) < a < max(c, e)) and (min(d, f) < b < max(d, f)):
                    return 2
            return 1

        # If neither piece can capture the queen in one move, it takes two moves
        return 2

