class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(prices)
        left_max_profit = [0] * n
        right_max_profit = [0] * n

        # Fill left_max_profit array
        current_max_profit = 0
        for i in range(n):
            if profits[i] > current_max_profit:
                current_max_profit = profits[i]
            left_max_profit[i] = current_max_profit

        # Fill right_max_profit array
        current_max_profit = 0
        for i in range(n-1, -1, -1):
            if profits[i] > current_max_profit:
                current_max_profit = profits[i]
            right_max_profit[i] = current_max_profit

        # Find the maximum profit for the triplet
        max_profit = -1
        for j in range(1, n-1):
            for i in range(j):
                if prices[i] < prices[j]:
                    for k in range(j+1, n):
                        if prices[j] < prices[k]:
                            max_profit = max(max_profit, left_max_profit[i] + profits[j] + right_max_profit[k])

        return max_profit

class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        slow = nums[0]
        fast = nums[0]

        # Phase 1: Finding the intersection point of the two runners
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break

        # Phase 2: Finding the entrance to the cycle
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]

        return slow

