class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        def is_magic(grid, r, c):
            # Check if all numbers are unique and between 1 and 9
            nums = set()
            for i in range(r, r + 3):
                for j in range(c, c + 3):
                    if grid[i][j] < 1 or grid[i][j] > 9:
                        return False
                    nums.add(grid[i][j])
            if len(nums) != 9:
                return False

            # Check rows, columns, and diagonals
            target_sum = sum(grid[r][c:c+3])
            for i in range(r, r + 3):
                if sum(grid[i][c:c+3]) != target_sum:
                    return False
                if sum(grid[j][i] for j in range(r, r + 3)) != target_sum:
                    return False
            if (grid[r][c] + grid[r+1][c+1] + grid[r+2][c+2] != target_sum) or \
               (grid[r][c+2] + grid[r+1][c+1] + grid[r+2][c] != target_sum):
                return False

            return True

        count = 0
        for i in range(len(grid) - 2):
            for j in range(len(grid[0]) - 2):
                if is_magic(grid, i, j):
                    count += 1
        return count

