class Solution:
    def recoverArray(self, nums: List[int]) -> List[int]:
        nums.sort()
        first = nums[0]
        n = len(nums)

        for i in range(1, n):
            diff = nums[i] - first
            if diff % 2 == 0 and diff > 0:
                k = diff // 2
                arr = []
                used = [False] * n
                for j in range(n):
                    if not used[j]:
                        lower = nums[j]
                        higher = lower + 2 * k
                        if higher in nums:
                            used[nums.index(higher)] = True
                            arr.append((lower + higher) // 2)
                        else:
                            break
                if len(arr) == n // 2:
                    return arr
        return []

