class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(parents)
        graph = [[] for _ in range(n)]
        for i in range(1, n):
            graph[parents[i]].append(i)

        def dfs(node):
            seen = set()
            for child in graph[node]:
                seen.update(dfs(child))
            seen.add(nums[node])
            return seen

        result = [1] * n
        if 1 not in nums:
            return result

        node_with_one = nums.index(1)
        current_value = 1
        while node_with_one != -1:
            seen_values = dfs(node_with_one)
            while current_value in seen_values:
                current_value += 1
            result[node_with_one] = current_value
            node_with_one = parents[node_with_one]

        return result

