class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums.sort()
        max_xor = 0
        left = 0

        for right in range(len(nums)):
            while nums[right] - nums[left] > nums[left]:
                left += 1
            for i in range(left, right + 1):
                max_xor = max(max_xor, nums[i] ^ nums[right])

        return max_xor

class Solution:
    def escapeGhosts(self, ghosts: List[List[int]], target: List[int]) -> bool:
        # Calculate the Manhattan distance from the target to the current position
        manhattan_distance = abs(target[0] - 0) + abs(target[1] - 0)

        # Check if the target is closer to any ghost than the Manhattan distance
        for ghost in ghosts:
            ghost_x, ghost_y = ghost[0], ghost[1]
            if abs(ghost_x - target[0]) + abs(ghost_y - target[1]) < manhattan_distance:
                return False

        return True

class Solution:
    def isStrobogrammatic(self, num: str) -> bool:
        # Mapping of each digit to its strobogrammatic counterpart
        strob_map = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}

        # Initialize two pointers
        left, right = 0, len(num) - 1

        # Iterate while the left pointer is less than the right pointer
        while left < right:
            # Check if both characters at the current pointers are valid strobogrammatic pairs
            if num[left] not in strob_map or num[right] != strob_map[num[left]]:
                return False
            # Move the pointers towards the center
            left += 1
            right -= 1

        # If all pairs are valid, return True
        return True

