class Solution:
    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        # Check if the total sum of numbers is not divisible by k
        if sum(nums) % k != 0:
            return False

        # Sort the array in descending order to prioritize larger numbers first
        nums.sort(reverse=True)

        # Helper function to check if the current subset sums up to target
        def dfs(target):
            if target == 0:
                return True
            for i in range(len(nums)):
                if nums[i] > target:
                    continue
                if nums[i] <= target and dfs(target - nums[i]):
                    return True
            return False

        # Start DFS from the largest number
        return dfs(sum(nums) // k)

class Solution:
    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:
        mapping_dict = {}
        for old_char, new_char in mappings:
            mapping_dict[old_char] = new_char

        for i in range(len(s) - len(sub) + 1):
            if self.is_substring_match(s, sub, mapping_dict, i):
                return True

        return False

    def is_substring_match(self, s, sub, mapping_dict, start_index):
        for j in range(len(sub)):
            if s[start_index + j] != sub[j]:
                if s[start_index + j] in mapping_dict and mapping_dict[s[start_index + j]] != sub[j]:
                    continue
                else:
                    return False
        return True

class Solution:
    def minimumMountainRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        left = [1] * n
        right = [1] * n

        # Fill left array
        for i in range(1, n):
            if nums[i] > nums[i - 1]:
                left[i] = left[i - 1] + 1

        # Fill right array
        for i in range(n - 2, -1, -1):
            if nums[i] > nums[i + 1]:
                right[i] = right[i + 1] + 1

        # Find the maximum length of the mountain
        max_length = 0
        for i in range(1, n - 1):
            if left[i] > 1 and right[i] > 1:
                max_length = max(max_length, left[i] + right[i] - 1)

        # Calculate the minimum removals needed
        return n - max_length

