class Solution:
    def maximumPopulation(self, logs: List[List[int]]) -> int:
        population_count = {}

        for birth, death in logs:
            for year in range(birth, death):
                if year in population_count:
                    population_count[year] += 1
                else:
                    population_count[year] = 1

        max_population = max(population_count.values())
        earliest_year = min(year for year, count in population_count.items() if count == max_population)

        return earliest_year

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def flipMatchVoyage(self, root: Optional[TreeNode], voyage: List[int]) -> List[int]:
        flip = []
        stack = [root]
        i = 0

        while stack:
            node = stack.pop()
            if not node:
                continue
            if node.val != voyage[i]:
                return [-1]
            i += 1
            if node.right and node.right.val == voyage[i]:
                if node.left:
                    flip.append(node.val)
                stack.extend([node.left, node.right])
            else:
                stack.extend([node.right, node.left])

        return flip

class Solution:
    def checkArithmeticSubarrays(self, nums: List[int], l: List[int], r: List[int]) -> List[bool]:

        def is_arithmetic(arr):
            arr.sort()
            diff = arr[1] - arr[0]
            return all(arr[i] - arr[i-1] == diff for i in range(2, len(arr)))

        return [is_arithmetic(nums[l[i]:r[i]+1]) for i in range(len(l))]

from typing import List

class Solution:
    def rankTeams(self, votes: List[str]) -> str:
        # Create a dictionary to store the rank counts for each team
        rank_counts = {team: [0] * len(votes[0]) for team in votes[0]}

        # Count the votes for each team at each position
        for vote in votes:
            for i, team in enumerate(vote):
                rank_counts[team][i] -= 1

        # Sort the teams first by their rank counts, then alphabetically
        sorted_teams = sorted(rank_counts.keys(), key=lambda team: (rank_counts[team], team))

        # Join the sorted teams into a single string
        return ''.join(sorted_teams)
